package cn.balltv.portal;
import org.junit.Test;import static org.junit.Assert.*;import org.json.*;import java.util.*;
public class AdaptersTest {
    @Test public void wrappersContainingVideoInQueryAreNotVideoFiles(){assertFalse(StreamResolver.direct("https://player.example/m3u8.html?url=https%3A%2F%2Fmedia.example%2Ftest.m3u8"));assertFalse(StreamResolver.direct("https://player.example/embed?url=https://media.example/test.m3u8"));assertTrue(StreamResolver.direct("https://media.example/test.m3u8?token=one"));}
    @Test public void encodedWrapperPreservesCompleteSignedQuery(){String u="https://player.example/m3u8.html?url=https%3A%2F%2Fmedia.example%2Fa.m3u8%3Ftoken%3Dabc%253D%26x%3D2";assertEquals("https://media.example/a.m3u8?token=abc%3D&x=2",StreamResolver.queryStream(u));}
    @Test public void protocolRelativeMediaInheritsWrapperScheme(){assertEquals("http://cdn.example/live.m3u8",StreamResolver.queryStream("http://player.example/msss.html?id=%2F%2Fcdn.example%2Flive.m3u8"));assertEquals("https://cdn.example/live.m3u8",StreamResolver.queryStream("https://player.example/msss.html?id=%2F%2Fcdn.example%2Flive.m3u8"));}
    @Test public void nestedPlayerWithEncodedVideoNeverReturnsHtmlAsMedia()throws Exception{Feeds.Line line=new Feeds.Line("test","","https://wrap.example/play/steam1.html");String url=StreamResolver.resolve(line,(u,ref)->{String body=u.contains("steam1")?"<iframe src='/play/sm.html?id=4'></iframe>":u.contains("sm.html")?"<script>var id1; var url='/play/'+id1+'.html';</script>":"<iframe src='https://player.example/msss.html?id=%2F%2Fcdn.example%2Fv.m3u8%3Ftoken%3Dabc'></iframe>";return new HttpData.Reply(u,body);});assertEquals("https://cdn.example/v.m3u8?token=abc",url);}
    @Test public void htmlListReads88DateTeamsAndOnlyLiveInLiveView()throws Exception{String html="<li class='list-group-item live-list-group-time'>2026-11-09</li><li class='list-group-item group-game-item'><span class='game-type'>NBA</span><span class='team-name'>国王</span><span class='team-name'>热火</span><span class='category-game-time'>10:00</span><a href='/live/123/play'>直播中</a></li><li class='list-group-item'><a href='/live/124/play'>未开始</a></li>";List<Feeds.Match> live=MoreSources.parse88(html,"live");assertEquals(1,live.size());assertEquals("国王",live.get(0).home);assertEquals("2026-11-09 10:00",live.get(0).time);assertEquals(2,MoreSources.parse88(html,"schedule").size());}
    @Test public void jsonpIsParsedWithoutExecutingCode()throws Exception{JSONObject o=(JSONObject)HttpData.json("detail({\"code\":200,\"data\":{\"ok\":true}});");assertTrue(o.getJSONObject("data").getBoolean("ok"));try{HttpData.json("evil(); detail({});");fail();}catch(java.io.IOException expected){}}
    @Test public void noisyBase64EnvelopeDecodesPublic88Links()throws Exception{String encoded="eyJsaW5rcyI6W3sidXJsIjoiaHR0cHM6Ly9tLmV4YW1wbGUvYS5tM3U4Iiwic2hhcmVMb2NrIjowfV19";JSONObject o=MoreSources.decode88(new JSONObject().put("data","abcdef"+encoded+"==xy"));assertEquals(1,o.getJSONArray("links").length());}
    @Test public void rainKeepsStableScheduleAndAnchorIds()throws Exception{JSONObject d=new JSONObject("{data:{matches:[{scheduleId:1,categoryId:2,subCateName:'NBA',hostName:'国王',guestName:'热火',status:1,matchTime:1794189600000,anchors:[{nickName:'原声',anchor:{roomNum:'55'}}]}]}}");Feeds.Match m=MoreSources.parseRain(d,"live").get(0);assertEquals("1",m.id);assertEquals("55",m.raw.getJSONObject("extra").getJSONArray("anchors").getJSONObject(0).getJSONObject("anchor").getString("roomNum"));Feeds.Page restored=Feeds.parse(MoreSources.RAIN,"live",new JSONObject().put("data",new JSONArray().put(m.raw)));assertEquals(m.time,restored.items.get(0).time);}
    @Test public void provider178CommentatorDuplicatesBecomeOneEvent()throws Exception{JSONObject d=new JSONObject("{data:{hot:[{tournament_id:5,type:2,home_team_zh:'甲',away_team_zh:'乙',member_id:10},{tournament_id:5,type:2,member_id:11}]}}");assertEquals(1,MoreSources.parse178(d,"live").size());}
    @Test public void provider74ReadsNestedMatchAndReplaySource()throws Exception{JSONArray response=new JSONArray("[{id:8,title:'全场回放',match:{id:55,home_team:{name:'甲'},away_team:{name:'乙'},category:{key:'football'},competition:{name:'联赛'},status:'finished',start_time:'2026-11-09T02:00:00.000Z'},sources:[]}]");Feeds.Match m=MoreSources.parse74(response,"replay").get(0);assertEquals("55",m.room);assertEquals("8",m.raw.getJSONObject("extra").getString("video_id"));assertEquals("replay",m.kind);}
    @Test public void urlsRejectLocalAndNonWebSchemes(){assertFalse(HttpData.publicUrl("file:///etc/passwd"));assertFalse(HttpData.publicUrl("http://127.0.0.1/api"));assertFalse(HttpData.publicUrl("http://192.168.1.1/"));assertFalse(HttpData.publicUrl("http://localhost/"));assertTrue(HttpData.publicUrl("https://example.com/path"));}
    @Test public void unsupportedReplayIsExplicitNotFalseEmptySuccess(){assertFalse(SourceCatalog.supports(MoreSources.JR,"replay"));assertTrue(SourceCatalog.supports(MoreSources.S74,"replay"));assertTrue(Arrays.asList(SourceCatalog.ALL).contains("看球通"));}
}
